Shader "Custom/SimpleColor"
{
    Properties
    {
        _Color("Color", Color) = (1, 1, 1, 1)
    }
    SubShader
    {
        Pass
        {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            float4 _Color;

            struct Attributes
            {
                float4 positionOS : POSITION;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionHCS = TransformObjectToHClip(input.positionOS);
                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                // Return the color property
                return _Color;
            }
            ENDHLSL
        }
    }
}

// Textured shader with UV support
Shader "Custom/Textured"
{
    Properties
    {
        _MainTex("Main Texture", 2D) = "white" {}
        _Color("Tint Color", Color) = (1,1,1,1)
    }
    SubShader
    {
        Pass
        {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            float4 _MainTex_ST;
            float4 _Color;

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv         : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionHCS : SV_POSITION;
                float2 uv          : TEXCOORD0;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionHCS = TransformObjectToHClip(input.positionOS);
                // Apply tiling and offset to UVs
                output.uv = TRANSFORM_TEX(input.uv, _MainTex);
                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                // Sample the texture at the UV coordinates
                half4 texColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                // Multiply by tint color
                return texColor * _Color;
            }
            ENDHLSL
        }
    }
}

// Scrolling UV effect (like flowing water or lava)
float _ScrollSpeedX;
float _ScrollSpeedY;

half4 frag(Varyings input) : SV_Target
{
    // Animate UVs over time
    float2 scrollUV = input.uv;
    scrollUV.x += _Time.y * _ScrollSpeedX;
    scrollUV.y += _Time.y * _ScrollSpeedY;

    // Sample with animated UVs
    half4 texColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, scrollUV);
    return texColor;
}

// UV Distortion (like heat haze or water refraction)
float _DistortionStrength;

half4 fragDistort(Varyings input) : SV_Target
{
    // Use a noise texture to offset the main UVs
    float2 noiseUV = input.uv + _Time.y * 0.1;
    half2 distortion = SAMPLE_TEXTURE2D(_NoiseTex, sampler_NoiseTex, noiseUV).rg;
    distortion = (distortion - 0.5) * _DistortionStrength;

    float2 finalUV = input.uv + distortion;
    return SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, finalUV);
}

// Transparent shader setup
SubShader
{
    Tags
    {
        "RenderType" = "Transparent"
        "Queue" = "Transparent"
        "RenderPipeline" = "UniversalPipeline"
    }

    Pass
    {
        // Enable blending: SrcAlpha * color + OneMinusSrcAlpha * background
        Blend SrcAlpha OneMinusSrcAlpha
        ZWrite Off  // Don't write to depth buffer for transparency

        HLSLPROGRAM
        // ... vertex and fragment code ...

        half4 frag(Varyings input) : SV_Target
        {
            half4 color = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
            color.a *= _Transparency; // Control overall transparency
            return color;
        }
        ENDHLSL
    }
}
